    "id": "20260518050000_harden_function_privileges",
    "sql": "REVOKE EXECUTE ON FUNCTION public.accept_trade_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.accept_trade_v2(uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.buy_listing_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.buy_listing_v2(uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.cancel_listing_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.cancel_listing_v2(uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.claim_asset_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.claim_asset_v2(uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.execute_trade(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.execute_trade(uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.publish_listing_v2(text, jsonb, bigint) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.publish_listing_v2(text, jsonb, bigint) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.save_game_trusted(jsonb, uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.save_game_trusted(jsonb, uuid) TO authenticated, service_role; REVOKE EXECUTE ON FUNCTION public.send_trade_offer_v2(uuid, jsonb, jsonb, bigint, jsonb, jsonb, bigint, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.send_trade_offer_v2(uuid, jsonb, jsonb, bigint, jsonb, jsonb, bigint, text) TO authenticated, service_role; INSERT INTO public.system_config (key, value) VALUES ('db_version', '20260518050000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();",
