    "sql": "DO $$ DECLARE r RECORD; v_save_data JSONB; v_team JSONB; v_box JSONB; v_new_team JSONB; v_new_box JSONB; v_poke JSONB; v_poke_id TEXT; v_species TEXT; v_pokedex JSONB; v_new_pokedex JSONB; v_seen_pokedex JSONB; v_new_seen_pokedex JSONB; v_val TEXT; v_species_map JSONB; v_species_key TEXT; BEGIN v_species_map := '{ \"nidoran_f\": \"nidoranf\", \"nidoran_m\": \"nidoranm\", \"mr_mime\": \"mrmime\", \"ho_oh\": \"hooh\", \"ho-oh\": \"hooh\" }'::jsonb; FOR r IN SELECT user_id, save_data FROM public.game_saves LOOP v_save_data := r.save_data; v_team := v_save_data -> 'team'; v_box := v_save_data -> 'box'; v_pokedex := v_save_data -> 'pokedex'; v_seen_pokedex := v_save_data -> 'seenPokedex'; IF v_team IS NOT NULL AND jsonb_typeof(v_team) = 'array' THEN v_new_team := '[]'::jsonb; FOR v_poke IN SELECT * FROM jsonb_array_elements(v_team) LOOP v_poke_id := v_poke ->> 'id'; IF v_poke_id IS NOT NULL THEN v_species_key := lower(v_poke_id); IF v_species_map ->> v_species_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{id}', to_jsonb(v_species_map ->> v_species_key)); END IF; END IF; v_species := v_poke ->> 'species'; IF v_species IS NOT NULL THEN v_species_key := lower(v_species); IF v_species_map ->> v_species_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{species}', to_jsonb(v_species_map ->> v_species_key)); END IF; END IF; v_new_team := v_new_team || v_poke; END LOOP; v_save_data := jsonb_set(v_save_data, '{team}', v_new_team); END IF; IF v_box IS NOT NULL AND jsonb_typeof(v_box) = 'array' THEN v_new_box := '[]'::jsonb; FOR v_poke IN SELECT * FROM jsonb_array_elements(v_box) LOOP v_poke_id := v_poke ->> 'id'; IF v_poke_id IS NOT NULL THEN v_species_key := lower(v_poke_id); IF v_species_map ->> v_species_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{id}', to_jsonb(v_species_map ->> v_species_key)); END IF; END IF; v_species := v_poke ->> 'species'; IF v_species IS NOT NULL THEN v_species_key := lower(v_species); IF v_species_map ->> v_species_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{species}', to_jsonb(v_species_map ->> v_species_key)); END IF; END IF; v_new_box := v_new_box || v_poke; END LOOP; v_save_data := jsonb_set(v_save_data, '{box}', v_new_box); END IF; IF v_pokedex IS NOT NULL AND jsonb_typeof(v_pokedex) = 'array' THEN v_new_pokedex := '[]'::jsonb; FOR v_val IN SELECT * FROM jsonb_array_elements_text(v_pokedex) LOOP IF v_species_map ->> v_val IS NOT NULL THEN v_new_pokedex := v_new_pokedex || to_jsonb(v_species_map ->> v_val); ELSE v_new_pokedex := v_new_pokedex || to_jsonb(v_val); END IF; END LOOP; v_save_data := jsonb_set(v_save_data, '{pokedex}', v_new_pokedex); END IF; IF v_seen_pokedex IS NOT NULL AND jsonb_typeof(v_seen_pokedex) = 'array' THEN v_new_seen_pokedex := '[]'::jsonb; FOR v_val IN SELECT * FROM jsonb_array_elements_text(v_seen_pokedex) LOOP IF v_species_map ->> v_val IS NOT NULL THEN v_new_seen_pokedex := v_new_seen_pokedex || to_jsonb(v_species_map ->> v_val); ELSE v_new_seen_pokedex := v_new_seen_pokedex || to_jsonb(v_val); END IF; END LOOP; v_save_data := jsonb_set(v_save_data, '{seenPokedex}', v_new_seen_pokedex); END IF; UPDATE public.game_saves SET save_data = v_save_data WHERE user_id = r.user_id; END LOOP; INSERT INTO public.system_config (key, value) VALUES ('db_version', '20260622000000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW(); END $$;",
    "sqlite_sql": "UPDATE game_saves SET save_data = json_set( save_data, '$.team', ( SELECT json_group_array( json_set( json_set( team_item.value, '$.id', coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(json_extract(team_item.value, '$.id')) ), json_extract(team_item.value, '$.id') ) ), '$.species', coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(json_extract(team_item.value, '$.species')) ), json_extract(team_item.value, '$.species') ) ) ) FROM json_each(json_extract(game_saves.save_data, '$.team')) team_item ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.team') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.box', ( SELECT json_group_array( json_set( json_set( box_item.value, '$.id', coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(json_extract(box_item.value, '$.id')) ), json_extract(box_item.value, '$.id') ) ), '$.species', coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(json_extract(box_item.value, '$.species')) ), json_extract(box_item.value, '$.species') ) ) ) FROM json_each(json_extract(game_saves.save_data, '$.box')) box_item ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.box') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.pokedex', ( SELECT json_group_array( coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(pk.value) ), pk.value ) ) FROM json_each(json_extract(game_saves.save_data, '$.pokedex')) pk ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.pokedex') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.seenPokedex', ( SELECT json_group_array( coalesce( json_extract( '{\"nidoran_f\":\"nidoranf\",\"nidoran_m\":\"nidoranm\",\"mr_mime\":\"mrmime\",\"ho_oh\":\"hooh\",\"ho-oh\":\"hooh\"}', '$.' || lower(pk.value) ), pk.value ) ) FROM json_each(json_extract(game_saves.save_data, '$.seenPokedex')) pk ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.seenPokedex') IS NOT NULL;",
