  {
    "id": "20260713180000_heal_pidgey_local_moves",
    "sql": "UPDATE game_saves SET save_data = jsonb_set( save_data::jsonb, '{team}', coalesce( ( SELECT jsonb_agg( CASE WHEN (t.value->>'uid') = '3b70c27d-9a1d-4632-becb-d46db26e2398' AND (t.value->'moves' IS NULL OR jsonb_array_length(t.value->'moves') = 0) THEN t.value || jsonb_build_object('moves', '[{\"id\":\"tackle\",\"name\":\"Tackle\",\"pp\":35,\"maxPP\":35,\"type\":\"normal\",\"acc\":100,\"cat\":\"physical\"}]'::jsonb) ELSE t.value END ) FROM jsonb_array_elements(save_data::jsonb->'team') t ), '[]'::jsonb ) )::json WHERE save_data IS NOT NULL AND (save_data::jsonb->'team') IS NOT NULL; UPDATE game_saves SET save_data = jsonb_set( save_data::jsonb, '{box}', coalesce( ( SELECT jsonb_agg( CASE WHEN (t.value->>'uid') = '3b70c27d-9a1d-4632-becb-d46db26e2398' AND (t.value->'moves' IS NULL OR jsonb_array_length(t.value->'moves') = 0) THEN t.value || jsonb_build_object('moves', '[{\"id\":\"tackle\",\"name\":\"Tackle\",\"pp\":35,\"maxPP\":35,\"type\":\"normal\",\"acc\":100,\"cat\":\"physical\"}]'::jsonb) ELSE t.value END ) FROM jsonb_array_elements(save_data::jsonb->'box') t ), '[]'::jsonb ) )::json WHERE save_data IS NOT NULL AND (save_data::jsonb->'box') IS NOT NULL;",
    "sqlite_sql": "UPDATE game_saves SET save_data = json_set( save_data, '$.team', ( SELECT json_group_array( CASE WHEN json_extract(team_item.value, '$.uid') = '3b70c27d-9a1d-4632-becb-d46db26e2398' AND (json_extract(team_item.value, '$.moves') IS NULL OR json_array_length(json_extract(team_item.value, '$.moves')) = 0) THEN json_set(team_item.value, '$.moves', json('[{\"id\":\"tackle\",\"name\":\"Tackle\",\"pp\":35,\"maxPP\":35,\"type\":\"normal\",\"acc\":100,\"cat\":\"physical\"}]')) ELSE team_item.value END ) FROM json_each(json_extract(game_saves.save_data, '$.team')) team_item ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.team') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.box', ( SELECT json_group_array( CASE WHEN json_extract(box_item.value, '$.uid') = '3b70c27d-9a1d-4632-becb-d46db26e2398' AND (json_extract(box_item.value, '$.moves') IS NULL OR json_array_length(json_extract(box_item.value, '$.moves')) = 0) THEN json_set(box_item.value, '$.moves', json('[{\"id\":\"tackle\",\"name\":\"Tackle\",\"pp\":35,\"maxPP\":35,\"type\":\"normal\",\"acc\":100,\"cat\":\"physical\"}]')) ELSE box_item.value END ) FROM json_each(json_extract(game_saves.save_data, '$.box')) box_item ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.box') IS NOT NULL;",
    "check": null
  },
  {
    "id": "20260714200000_fix_fossils_and_missing_item_ids",
    "sql": "DO $$ DECLARE r RECORD; v_save_data JSONB; v_inventory JSONB; v_new_inventory JSONB; v_team JSONB; v_new_team JSONB; v_box JSONB; v_new_box JSONB; v_poke JSONB; v_inv_key TEXT; v_inv_val INT; v_clean_key TEXT; v_item TEXT; v_official_keys JSONB; BEGIN v_official_keys := '{ \"old_amber\": \"oldamber\", \"helix_fossil\": \"helixfossil\", \"dome_fossil\": \"domefossil\", \"brush_super\": \"brushsuper\", \"brush_good\": \"brushgood\", \"spell_tag\": \"spelltag\", \"light_ball\": \"lightball\", \"thick_club\": \"thickclub\" }'::jsonb; FOR r IN SELECT user_id, save_data FROM public.game_saves LOOP v_save_data := r.save_data; v_inventory := v_save_data -> 'inventory'; IF v_inventory IS NOT NULL AND jsonb_typeof(v_inventory) = 'object' THEN v_new_inventory := '{}'::jsonb; FOR v_inv_key, v_inv_val IN SELECT * FROM jsonb_each_text(v_inventory) LOOP v_clean_key := v_official_keys ->> v_inv_key; IF v_clean_key IS NULL THEN v_clean_key := v_inv_key; END IF; IF v_new_inventory ->> v_clean_key IS NOT NULL THEN v_new_inventory := jsonb_set(v_new_inventory, ARRAY[v_clean_key], to_jsonb((v_new_inventory ->> v_clean_key)::INTEGER + v_inv_val::INTEGER)); ELSE v_new_inventory := jsonb_set(v_new_inventory, ARRAY[v_clean_key], to_jsonb(v_inv_val::INTEGER)); END IF; END LOOP; v_save_data := jsonb_set(v_save_data, '{inventory}', v_new_inventory); END IF; v_team := v_save_data -> 'team'; IF v_team IS NOT NULL AND jsonb_typeof(v_team) = 'array' THEN v_new_team := '[]'::jsonb; FOR v_poke IN SELECT * FROM jsonb_array_elements(v_team) LOOP v_item := v_poke ->> 'heldItem'; IF v_item IS NOT NULL THEN v_clean_key := v_official_keys ->> v_item; IF v_clean_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{heldItem}', to_jsonb(v_clean_key)); END IF; END IF; v_new_team := v_new_team || v_poke; END LOOP; v_save_data := jsonb_set(v_save_data, '{team}', v_new_team); END IF; v_box := v_save_data -> 'box'; IF v_box IS NOT NULL AND jsonb_typeof(v_box) = 'array' THEN v_new_box := '[]'::jsonb; FOR v_poke IN SELECT * FROM jsonb_array_elements(v_box) LOOP v_item := v_poke ->> 'heldItem'; IF v_item IS NOT NULL THEN v_clean_key := v_official_keys ->> v_item; IF v_clean_key IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{heldItem}', to_jsonb(v_clean_key)); END IF; END IF; v_new_box := v_new_box || v_poke; END LOOP; v_save_data := jsonb_set(v_save_data, '{box}', v_new_box); END IF; UPDATE public.game_saves SET save_data = v_save_data WHERE user_id = r.user_id; END LOOP; UPDATE public.profiles SET db_version = 18; ALTER TABLE public.profiles ALTER COLUMN db_version SET DEFAULT 18; END $$; INSERT INTO public.system_config (key, value) VALUES ('db_version', '20260714200000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();",
    "sqlite_sql": "UPDATE game_saves SET save_data = json_set( save_data, '$.inventory', json( ( SELECT json_group_object(clean_key, sum_value) FROM ( SELECT coalesce( json_extract( '{\"old_amber\":\"oldamber\",\"helix_fossil\":\"helixfossil\",\"dome_fossil\":\"domefossil\",\"brush_super\":\"brushsuper\",\"brush_good\":\"brushgood\",\"spell_tag\":\"spelltag\",\"light_ball\":\"lightball\",\"thick_club\":\"thickclub\"}', '$.' || lower(inv.key) ), lower(inv.key) ) AS clean_key, SUM(CAST(inv.value AS INTEGER)) AS sum_value FROM json_each(json_extract(game_saves.save_data, '$.inventory')) inv GROUP BY clean_key ) ) ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.inventory') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.team', json( ( SELECT json_group_array( json_set( team_item.value, '$.heldItem', coalesce( json_extract( '{\"old_amber\":\"oldamber\",\"helix_fossil\":\"helixfossil\",\"dome_fossil\":\"domefossil\",\"brush_super\":\"brushsuper\",\"brush_good\":\"brushgood\",\"spell_tag\":\"spelltag\",\"light_ball\":\"lightball\",\"thick_club\":\"thickclub\"}', '$.' || lower(json_extract(team_item.value, '$.heldItem')) ), json_extract(team_item.value, '$.heldItem') ) ) ) FROM json_each(json_extract(game_saves.save_data, '$.team')) team_item ) ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.team') IS NOT NULL; UPDATE game_saves SET save_data = json_set( save_data, '$.box', json( ( SELECT json_group_array( json_set( box_item.value, '$.heldItem', coalesce( json_extract( '{\"old_amber\":\"oldamber\",\"helix_fossil\":\"helixfossil\",\"dome_fossil\":\"domefossil\",\"brush_super\":\"brushsuper\",\"brush_good\":\"brushgood\",\"spell_tag\":\"spelltag\",\"light_ball\":\"lightball\",\"thick_club\":\"thickclub\"}', '$.' || lower(json_extract(box_item.value, '$.heldItem')) ), json_extract(box_item.value, '$.heldItem') ) ) ) FROM json_each(json_extract(game_saves.save_data, '$.box')) box_item ) ) ) WHERE save_data IS NOT NULL AND json_extract(save_data, '$.box') IS NOT NULL;",
    "check": null
  }
